-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'INTRODUCAO TIC' and a.numero = 10
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 10 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('PESQUISA INTERNET', 'PENDENTE', v_aula, 'Atividade — PESQUISA INTERNET (30 questões discursivas)',
      '/MATERIAIS/ASSISTENTE-DE-OPERACOES-LOGISTICAS/INTRODUCAO-TIC/ATIVIDADES/ATIVIDADE-PESQUISA-INTERNET.html', 30, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Autores, ano, elementos do modelo, conceito de ruído e exemplo no almoxarifado.', 1.0, 'Claude Shannon e Warren Weaver publicaram o modelo matemático da comunicação em 1949 (a partir do artigo de Shannon de 1948). Elementos: fonte de informação, emissor/transmissor, mensagem, canal, sinal, receptor e destino; o ruído é tudo o que interfere no sinal e distorce a mensagem entre o emissor e o receptor. Exemplo: barulho das empilhadeiras durante um pedido falado, ou uma etiqueta borrada.', 'Nota cheia: Shannon e Weaver, 1949 (ou 1948), pelo menos quatro elementos, conceito de ruído e exemplo coerente. Metade: autores e ano corretos com elementos ou ruído incompletos. Zero: autores errados ou em branco.'),
      (v_atividade, 2, 1, 'Conceito de comunicação assertiva, diferença entre os três estilos e exemplo de fala assertiva.', 1.0, 'Comunicação assertiva é expressar ideias, opiniões e limites de forma clara, direta e respeitosa, sem desrespeitar o outro e sem deixar de defender o próprio ponto. Passivo: evita conflito, não fala o que pensa (o colega calado). Agressivo: impõe, ofende ou intimida (o conferente). Assertivo: fala o fato, o impacto e o pedido com respeito. Ex.: "O agendamento era às 8h; com o atraso a doca ficou parada. Vou encaixar a descarga às 10h e peço que avise com antecedência da próxima vez."', 'Nota cheia: conceito, os três estilos diferenciados e exemplo de fala assertiva. Metade: conceito sem a diferença dos estilos, ou estilos sem exemplo. Zero: conceito errado ou em branco.'),
      (v_atividade, 3, 1, 'Conceito de comunicação não verbal, quatro formas e efeito no atendimento.', 1.0, 'Comunicação não verbal é a mensagem passada sem palavras. Formas: expressões faciais (sorriso ou cara fechada), gestos (apontar, cruzar os braços), postura corporal, contato visual, tom e volume de voz (paralinguagem), distância entre as pessoas (proxêmica) e aparência/uniforme. No atendimento: olhar nos olhos, postura aberta e tom calmo mostram respeito; braços cruzados, olhar no celular e tom ríspido passam descaso, mesmo com as palavras certas.', 'Nota cheia: conceito, quatro formas corretas e efeito no atendimento. Metade: duas ou três formas, ou formas sem o efeito no atendimento. Zero: confunde com comunicação escrita ou em branco.'),
      (v_atividade, 4, 1, 'Intel 4004, Intel, 1971, Lei de Moore e Gordon Moore.', 1.0, 'O primeiro microprocessador comercial foi o Intel 4004, lançado pela Intel em 1971, com cerca de 2.300 transistores. A Lei de Moore foi formulada por Gordon Moore, cofundador da Intel, em 1965 (revista em 1975): o número de transistores num chip dobra aproximadamente a cada dois anos, o que torna os processadores mais rápidos, menores e mais baratos com o tempo.', 'Nota cheia: Intel 4004, Intel, 1971, conceito da Lei de Moore e Gordon Moore. Metade: só a primeira parte ou só a Lei de Moore. Zero: dados errados ou em branco.'),
      (v_atividade, 5, 1, 'Funcionamento dos dois, comparação em três pontos e recomendação justificada.', 1.0, 'O HDD grava os dados em discos magnéticos que giram, lidos por uma cabeça que se move (partes mecânicas). O SSD usa memória flash, sem partes móveis. O SSD é muito mais rápido para ligar o computador e abrir programas, resiste melhor a quedas e vibração e gasta menos energia; o HDD é mais barato por GB e serve para guardar muito volume. Recomendação: SSD na expedição, porque o problema é a lentidão e o ambiente tem vibração.', 'Nota cheia: funcionamento dos dois, os três pontos e recomendação do SSD justificada. Metade: comparação incompleta ou recomendação sem justificativa. Zero: troca as características ou em branco.'),
      (v_atividade, 6, 1, 'Conceito de sistema operacional, funções e origem dos três sistemas.', 1.0, 'Sistema operacional é o programa principal que gerencia o hardware e permite que os outros programas e o usuário usem o computador. Funções: gerenciar processador e memória, arquivos e pastas, dispositivos e periféricos, executar programas, controlar usuários e segurança e oferecer a interface. Windows: Microsoft. Linux: núcleo criado por Linus Torvalds em 1991, mantido por uma comunidade (software livre). Android: Google, baseado no Linux, usado em celulares e coletores.', 'Nota cheia: conceito, pelo menos três funções e a origem dos três sistemas. Metade: conceito com funções sem a origem, ou origem sem as funções. Zero: confunde com aplicativo ou em branco.'),
      (v_atividade, 7, 1, 'Diferença entre Internet e Web, criador da Web, local, ano e origem da Internet.', 1.0, 'A Internet é a rede mundial de computadores interligados (a infraestrutura de cabos, roteadores e protocolos TCP/IP). A World Wide Web é um dos serviços que rodam sobre a Internet: páginas ligadas por hiperlinks, acessadas pelo navegador (HTTP e HTML); e-mail e WhatsApp também usam a Internet sem ser a Web. A Web foi criada por Tim Berners-Lee no CERN, na Suíça, em 1989 (primeiro site em 1991). A Internet nasceu da ARPANET, rede militar americana de 1969.', 'Nota cheia: diferença correta, Tim Berners-Lee, CERN, 1989 (ou 1990/1991) e ARPANET. Metade: diferença correta com dados históricos incompletos. Zero: diz que são iguais ou em branco.'),
      (v_atividade, 8, 1, 'Explicação dos quatro operadores e busca montada com pelo menos três.', 1.0, 'Aspas ("...") buscam a frase exata; site: limita a busca a um site ou domínio (site:gov.br); filetype: traz só um tipo de arquivo (filetype:pdf); o sinal de menos tira uma palavra dos resultados (-loja). Exemplo: "armazenagem de produtos químicos" site:gov.br filetype:pdf -comprar. Assim aparecem só documentos oficiais em PDF, sem anúncios. Também dá para usar OR entre duas palavras e a Pesquisa avançada do Google.', 'Nota cheia: os quatro operadores corretos e busca com pelo menos três. Metade: operadores corretos sem a busca montada, ou busca correta com explicação incompleta. Zero: operadores errados ou em branco.'),
      (v_atividade, 9, 1, 'Quatro critérios de confiabilidade, duas agências de checagem e passo a passo para a notícia.', 1.0, 'Critérios: conferir quem é o autor e o site (fonte oficial, como gov.br ou Planalto, ou veículo conhecido); ver a data; procurar a mesma informação em outras fontes confiáveis; desconfiar de títulos alarmantes e erros de escrita; ver se cita a lei ou o documento original. Agências: Agência Lupa, Aos Fatos, Fato ou Fake (G1), Estadão Verifica, Comprova. Para a notícia: buscar o número da lei no site do Planalto ou do Diário Oficial e nas agências de checagem antes de repassar.', 'Nota cheia: quatro critérios, duas agências reais e o passo a passo. Metade: critérios sem agências ou sem o passo a passo. Zero: só diz "pesquisar no Google" ou em branco.'),
      (v_atividade, 10, 1, 'Limite de 25 MB, comportamento acima do limite, forma de envio e corpo do e-mail.', 1.0, 'O Gmail permite enviar até 25 MB de anexos por mensagem. Acima disso ele não anexa: coloca o arquivo no Google Drive e envia um link. O relatório deve ser salvo no Drive (ou outra nuvem), com o compartilhamento dado só às pessoas da qualidade, e o link vai no e-mail. No corpo: saudação, dizer que o relatório das avarias está no link, o que ele contém, o prazo e pedir a confirmação do recebimento.', 'Nota cheia: 25 MB, link do Drive acima do limite, permissão adequada e o que escrever. Metade: limite correto sem a forma de envio, ou envio correto sem o limite. Zero: limite errado e envio inadequado, ou em branco.'),
      (v_atividade, 11, 1, 'Conceito de nuvem e os três modelos com exemplos.', 1.0, 'Computação em nuvem é o uso de recursos de computação (armazenamento, servidores, programas) pela internet, sob demanda, pagando pelo uso, sem precisar ter a máquina na empresa. IaaS (infraestrutura como serviço): aluga servidores, rede e armazenamento virtuais (ex.: Amazon EC2, Azure Máquinas Virtuais). PaaS (plataforma como serviço): ambiente pronto para criar e rodar sistemas (ex.: Google App Engine, Heroku). SaaS (software como serviço): o programa pronto pelo navegador (ex.: Gmail, Google Drive, Microsoft 365).', 'Nota cheia: conceito e os três modelos com exemplos corretos. Metade: conceito com dois modelos, ou modelos sem exemplos. Zero: confunde os modelos ou em branco.'),
      (v_atividade, 12, 1, 'Conceito e origem da palavra e cinco regras.', 1.0, 'Netiqueta vem da junção de "net" (rede) com "etiqueta": é o conjunto de regras de boa educação na comunicação pela internet. Regras: não escrever tudo em maiúsculas (é como gritar); usar "Responder a todos" só quando todos precisam da resposta; assunto claro; saudação e despedida; revisar antes de enviar; não repassar correntes e boatos; responder em tempo razoável; respeitar o horário dos colegas; usar CCO para muitos destinatários externos.', 'Nota cheia: conceito, origem e cinco regras. Metade: conceito com três ou quatro regras. Zero: conceito errado ou em branco.'),
      (v_atividade, 13, 1, 'Número e ano, vigência, ANPD, multa máxima e mudança na planilha.', 1.0, 'LGPD é a Lei Geral de Proteção de Dados Pessoais, Lei nº 13.709/2018. Entrou em vigor em setembro de 2020, e as sanções passaram a valer em agosto de 2021. Quem fiscaliza é a ANPD (Autoridade Nacional de Proteção de Dados). A multa simples pode chegar a 2% do faturamento da empresa no Brasil, limitada a R$ 50 milhões por infração (art. 52). Na planilha: limitar o acesso só a quem precisa, guardar só os dados necessários, proteger com senha e registrar quem acessa.', 'Nota cheia: lei e ano, vigência, ANPD, multa e pelo menos uma mudança coerente. Metade: três desses itens. Zero: dados errados ou em branco.'),
      (v_atividade, 14, 1, 'Conceito de phishing, quatro sinais e conduta correta.', 1.0, 'Phishing é um golpe em que o criminoso se passa por uma empresa ou pessoa conhecida (banco, loja, chefe) para fazer a vítima clicar num link falso, baixar um arquivo ou informar senhas e dados. Sinais: urgência ou ameaça ("em 2 horas"); remetente com endereço estranho; link que leva a outro site (passar o mouse antes); erros de português; pedido de senha ou código (bancos não pedem); anexos inesperados. O que fazer: não clicar, não responder, apagar e avisar a TI; conferir pelo aplicativo ou telefone oficial do banco.', 'Nota cheia: conceito, quatro sinais e conduta correta. Metade: conceito com dois ou três sinais, ou sem a conduta. Zero: diz para clicar e conferir, ou em branco.'),
      (v_atividade, 15, 1, 'Regras de senha forte, conceito de 2FA e risco da senha repetida.', 1.0, 'Senha forte: longa (pelo menos 12 caracteres, ou uma frase-senha), misturando letras maiúsculas e minúsculas, números e símbolos, sem dados pessoais (data de nascimento, nome) nem sequências (123456). Usar um gerenciador de senhas ajuda a ter uma senha diferente para cada serviço. A verificação em duas etapas pede, além da senha, um segundo fator: código no aplicativo autenticador, SMS ou chave física. Se a mesma senha vazar num site, o criminoso tenta ela em todos os outros e invade várias contas.', 'Nota cheia: regras da senha forte, conceito de 2FA e risco da repetição. Metade: dois desses três pontos. Zero: regras erradas ou em branco.'),
      (v_atividade, 16, 1, 'Papel, margens, fonte, espaçamento e como configurar no editor.', 1.0, 'Pela ABNT NBR 14724: papel A4; margens superior e esquerda de 3 cm e inferior e direita de 2 cm; fonte tamanho 12 no texto (citações longas, notas e legendas menores); espaçamento de 1,5 entre linhas no texto; fonte comum é Arial ou Times New Roman. No Word: guia Layout > Margens > Margens Personalizadas, digitar os valores e aplicar ao documento inteiro (no Google Docs: Arquivo > Configuração da página).', 'Nota cheia: papel, margens, fonte, espaçamento e o caminho no editor. Metade: margens corretas sem o restante, ou dados corretos sem como configurar. Zero: margens erradas ou em branco.'),
      (v_atividade, 17, 1, 'Cinco atalhos corretos com a função e a vantagem dos atalhos.', 1.0, 'Word em português: Ctrl+N = negrito; Ctrl+I = itálico; Ctrl+S = sublinhado; Ctrl+B = salvar; Ctrl+E = centralizar; Ctrl+J = justificar; Ctrl+Z = desfazer; Ctrl+C / Ctrl+V = copiar / colar; Ctrl+P = imprimir; Ctrl+L = localizar. (No Word em inglês e no Google Docs, negrito é Ctrl+B e itálico Ctrl+I.) Os atalhos evitam tirar a mão do teclado e procurar menus, deixando a digitação e a formatação mais rápidas.', 'Nota cheia: cinco atalhos corretos com função e a vantagem. Metade: três ou quatro atalhos, ou sem a vantagem. Zero: atalhos errados ou em branco.'),
      (v_atividade, 18, 1, 'Estilos de título, inserir o sumário e atualizar.', 1.0, 'Primeiro aplica-se os estilos Título 1, Título 2… (guia Página Inicial > Estilos) aos títulos dos capítulos e seções; é por eles que o editor sabe o que entra no sumário. Depois, com o cursor no lugar do sumário: Referências > Sumário > Sumário Automático (no Google Docs: Inserir > Sumário). Quando o texto mudar, clicar no sumário > Atualizar Sumário (atualizar só os números de página ou o índice inteiro). Assim os números ficam sempre certos e os títulos viram links.', 'Nota cheia: estilos de título, como inserir e como atualizar. Metade: dois desses três pontos. Zero: sumário digitado à mão ou em branco.'),
      (v_atividade, 19, 1, 'Norma NBR 6023, elementos da referência online e exemplo.', 1.0, 'A norma é a ABNT NBR 6023 (Informação e documentação — Referências). A referência de site tem: AUTOR (pessoa ou instituição, em maiúsculas), título da página (em destaque), local/editora ou site, data de publicação (se houver), "Disponível em:" com o endereço e "Acesso em:" com a data em que foi consultado. Exemplo: BRASIL. Agência Nacional de Vigilância Sanitária. Boas práticas de armazenagem. Brasília: Anvisa, 2023. Disponível em: https://www.gov.br/anvisa. Acesso em: 21 out. 2026.', 'Nota cheia: NBR 6023, elementos e exemplo com Disponível em e Acesso em. Metade: norma correta com exemplo incompleto. Zero: norma errada e sem exemplo, ou em branco.'),
      (v_atividade, 20, 1, 'As três partes da estrutura com exemplos.', 1.0, 'A ABNT NBR 10719 organiza o relatório técnico em três partes. Pré-textuais (antes do texto): capa (opcional), folha de rosto, resumo, listas de ilustrações e tabelas, sumário. Textuais: introdução (objetivo e motivo), desenvolvimento (método, dados, análise das perdas) e considerações finais (conclusões e recomendações). Pós-textuais: referências (obrigatórias), glossário, apêndices (material do autor) e anexos (material de terceiros).', 'Nota cheia: as três partes com exemplos corretos. Metade: duas partes, ou as três sem exemplos. Zero: estrutura errada ou em branco.'),
      (v_atividade, 21, 1, 'Conceito da ISO, o que é a ISO 9001 e benefícios na logística.', 1.0, 'A ISO (Organização Internacional de Normalização) é uma entidade internacional, com sede em Genebra, que publica normas técnicas usadas no mundo todo; no Brasil a representante é a ABNT. A ISO 9001 é a norma do Sistema de Gestão da Qualidade: define requisitos para padronizar processos, documentar procedimentos, medir resultados, tratar falhas e buscar a melhoria contínua e a satisfação do cliente. Na logística: menos erros de separação e de expedição, processos iguais em todos os turnos, rastreabilidade e mais confiança dos clientes (abre portas para novos contratos).', 'Nota cheia: conceito da ISO, da ISO 9001 e pelo menos dois benefícios. Metade: dois desses três pontos. Zero: confunde com lei ou em branco.'),
      (v_atividade, 22, 1, 'Uso, sintaxe com os argumentos, FALSO e fórmula do caso.', 1.0, 'PROCV procura um valor na primeira coluna de uma tabela e devolve o valor de outra coluna da mesma linha. Sintaxe: =PROCV(valor_procurado; matriz_tabela; núm_índice_coluna; [procurar_intervalo]). valor_procurado = o código; matriz_tabela = a tabela onde procurar (A2:C500); núm_índice_coluna = número da coluna a devolver (3 = preço); FALSO = correspondência exata (só traz se achar o código igual). Fórmula: =PROCV(E2;$A$2:$C$500;3;FALSO), com o código digitado em E2.', 'Nota cheia: uso, sintaxe explicada, FALSO e fórmula correta. Metade: uso e sintaxe sem a fórmula, ou fórmula sem explicação. Zero: função errada ou em branco.'),
      (v_atividade, 23, 1, 'Uso, sintaxe e fórmula explicada.', 1.0, 'SOMASE soma apenas os valores que atendem a um critério. Sintaxe: =SOMASE(intervalo; critério; [intervalo_soma]). intervalo = onde o critério é testado (A2:A200, os setores); critério = a condição ("Manutenção"); intervalo_soma = os valores que serão somados (B2:B200). Fórmula: =SOMASE(A2:A200;"Manutenção";B2:B200). Para mais de um critério existe a SOMASES.', 'Nota cheia: uso, sintaxe e fórmula correta explicada. Metade: fórmula correta sem explicação, ou explicação sem fórmula. Zero: usa SOMA simples ou em branco.'),
      (v_atividade, 24, 1, 'Os três tipos, cifrão, F4 e fórmula corrigida.', 1.0, 'Referência relativa (A1) muda quando a fórmula é copiada ou arrastada; absoluta ($A$1) não muda, fica travada na mesma célula; mista ($A1 ou A$1) trava só a coluna ou só a linha. O cifrão ($) trava a parte que vem depois dele. A tecla F4, com o cursor na referência, alterna entre os tipos. Correção: =B2*$F$1, assim ao arrastar a quantidade muda (B3, B4…) e o dólar fica sempre em F1.', 'Nota cheia: três tipos, cifrão, F4 e fórmula corrigida. Metade: dois tipos com a fórmula, ou explicação sem a fórmula. Zero: fórmula errada e sem explicação, ou em branco.'),
      (v_atividade, 25, 1, 'Uso do gráfico de dispersão, leitura da relação e linha de tendência.', 1.0, 'O gráfico de dispersão (XY) mostra a relação entre duas variáveis numéricas: cada carregamento vira um ponto, com o peso no eixo X e o tempo no eixo Y. Se os pontos sobem juntos, há relação positiva (mais peso, mais tempo); se descem, negativa; se ficam espalhados, não há relação clara. A linha de tendência é a reta que melhor resume os pontos e mostra a direção da relação, ajudando a prever o tempo de um carregamento pelo peso.', 'Nota cheia: uso, leitura da relação e linha de tendência. Metade: uso correto sem a linha de tendência ou sem a leitura. Zero: confunde com pizza ou em branco.'),
      (v_atividade, 26, 1, 'Regra 80/20, Vilfredo Pareto, formato do gráfico e uso nas avarias.', 1.0, 'O Princípio de Pareto diz que cerca de 80% dos efeitos vêm de 20% das causas; leva o nome do economista italiano Vilfredo Pareto e foi levado para a qualidade por Joseph Juran. O gráfico de Pareto tem barras em ordem decrescente (do tipo de avaria mais frequente ao menos frequente) e uma linha com a porcentagem acumulada. Nas avarias, mostra os poucos tipos que causam a maior parte dos problemas, que devem ser resolvidos primeiro. A curva ABC do estoque usa a mesma ideia.', 'Nota cheia: regra 80/20, Pareto, barras decrescentes com linha acumulada e uso nas avarias. Metade: dois ou três desses pontos. Zero: conceito errado ou em branco.'),
      (v_atividade, 27, 1, 'Quando usar a pizza, quando evitar e gráfico melhor justificado.', 1.0, 'A pizza serve para mostrar as partes de um todo (que somam 100%) num único momento, com poucas categorias (até cerca de 5 ou 6), como a divisão do estoque por setor. Deve ser evitada com muitas categorias (as fatias ficam parecidas e difíceis de comparar), para comparar valores próximos e para mostrar evolução no tempo. No caso do colega, o melhor é o gráfico de linhas (evolução nos 12 meses) ou o de colunas/barras para comparar os fornecedores.', 'Nota cheia: quando usar, quando evitar e gráfico de linhas ou colunas justificado. Metade: dois desses pontos. Zero: aprova a pizza ou em branco.'),
      (v_atividade, 28, 1, 'Os três números explicados e o motivo.', 1.0, 'A regra 10-20-30 foi criada por Guy Kawasaki: no máximo 10 slides, no máximo 20 minutos de apresentação e fonte de no mínimo 30 pontos. Com poucos slides, a apresentação fica focada nas ideias principais; com 20 minutos sobra tempo para perguntas; com fonte 30 cabe pouco texto em cada slide, então o apresentador explica com as próprias palavras em vez de ler, e o público consegue enxergar.', 'Nota cheia: os três números corretos e o motivo. Metade: números corretos sem o motivo, ou dois números com o motivo. Zero: números errados ou em branco.'),
      (v_atividade, 29, 1, 'Lei 9.610/1998, Creative Commons, dois bancos de imagens e uso correto.', 1.0, 'No Brasil, os direitos autorais são protegidos pela Lei nº 9.610/1998: a imagem tem dono e usar sem autorização pode ser crime ou gerar processo. Creative Commons são licenças em que o autor já autoriza o uso com algumas condições (ex.: citar o autor, não usar comercialmente). Bancos gratuitos: Unsplash, Pexels, Pixabay, Freepik (com atribuição). Uso correto: baixar de bancos livres ou com licença, respeitar as condições da licença e citar a fonte/autor no slide; no Google Imagens, filtrar por "Licenças Creative Commons".', 'Nota cheia: lei, Creative Commons, dois bancos e uso correto. Metade: dois ou três desses pontos. Zero: diz que tudo da internet é livre ou em branco.'),
      (v_atividade, 30, 1, 'Cinco práticas de acessibilidade e a ferramenta do PowerPoint.', 1.0, 'Práticas: alto contraste entre texto e fundo; fonte grande e sem serifa (Arial, Calibri); pouco texto por slide; texto alternativo (descrição) nas imagens e gráficos; legendas nos vídeos (e legendas ao vivo do PowerPoint); não passar informação só pela cor; títulos em todos os slides; ordem de leitura correta; enviar o material antes. No PowerPoint: guia Revisão > Verificar Acessibilidade, que mostra os problemas e como corrigir.', 'Nota cheia: cinco práticas e o Verificador de Acessibilidade. Metade: três ou quatro práticas, ou práticas sem a ferramenta. Zero: em branco ou práticas que não tratam de acessibilidade.');
end $$;
